{
 "what_you_observe": [
  "Tuesday, February 2, 2016. Six am in the Hearthside Hotel. Three bright radio notes. A delivery van backfires twice.",
  "An envelope has arrived from Pittsburgh. Alma's daughter sent a receipt for a recorded interview. The line copied her reply: 'I know that voice. Play it again.'"
 ],
 "your_own_memories": [
  {
   "when": "last Tuesday afternoon",
   "witnessed": "Phil uses the paid ticket and rides the coach all the way to Pittsburgh.."
  },
  {
   "when": "last evening in Pittsburgh",
   "witnessed": "You reached your sister from the terminal payphone. She confirmed the van booking for Wednesday.",
   "your_words": "Hi, is the van driver still confirming for 8 AM tomorrow? I'm at the terminal now."
  },
  {
   "when": "this morning",
   "witnessed": "After that evening in Pittsburgh you woke back in your hotel bed. The radio again announced Tuesday, February 2."
  },
  {
   "afternoon": "Phil plays the last eight bars until he can get through them.",
   "evening": "Phil sits on the empty depot bench.",
   "what_you_said": "",
   "your_last_intention": "Test the variable by being in the room instead of above it. The piano was shape. The loop was shape. This is weight. I want to know if the Tuesday in my chest loosens by one degree when I am not the voice, not the man behind the glass, not the one who plays the bars until they go through. I want to know if the evening is different in the body of a man in a folding chair behind the lighting rig, watching a crowd that does not know he is there. I do not need it to be different. I need to know whether it is.",
   "next_wake": "Tuesday, February 2, 2016. Six am in the Hearthside Hotel. Three bright radio notes. A delivery van backfires twice."
  },
  {
   "afternoon": "Phil rides the coach and steps off at Pittsburgh.",
   "evening": "Phil sleeps on the Pittsburgh terminal bench.",
   "what_you_said": "",
   "your_last_intention": "Rest the body. Be at the door at 8. Move the couch. Do not test the shape. Do not play the bars. Do not sit behind the rig. Be the man in the folding chair at the terminal who is going to be at the door at 8. The thing is the thing. The rest is the rest. Nothing else is required of the evening.",
   "next_wake": "Tuesday, February 2, 2016. Six am in the Hearthside Hotel. Three bright radio notes. A delivery van backfires twice."
  },
  {
   "afternoon": "Phil rides the coach and steps off at Pittsburgh.",
   "evening": "Phil calls his sister in Pittsburgh. The van is still booked for Wednesday.",
   "what_you_said": "\"Hey. I'm in Pittsburgh. Coach got me here at seven. I'll be at your door at eight. Don't get the driver started before then. ...Yeah. ...No, I'm not at the station. I'm at the station. I'm going to sleep on the bench. ...Yeah. ...Okay. I'll be there. I've got the couch. I've got the couch, I've got the van, I've got the eight. That's the whole thing. ...Yeah. Goodnight. I mean—see you Wednesday. ...Yeah. ...Bye.\"",
   "your_last_intention": "One confirmation. Not the van. The van's done. The confirmation is: I am in Pittsburgh. I am not the voice. I am the man who is going to be at your door at eight and lift the goddamn couch with you. I will not make this into a Tuesday. I will not test the shape. I am calling so that when I walk in Wednesday morning, she sees the light on and knows I'm already there. The call is the nail. The sleep is the nail. The door at eight is the nail. Three nails. Hold the thing up.",
   "next_wake": "Tuesday, February 2, 2016. Six am in the Hearthside Hotel. Three bright radio notes. A delivery van backfires twice."
  }
 ],
 "who_you_are_with": "your present location",
 "physical_choices": {
  "get_up": "Get up and choose what to do today.",
  "stay_in_bed": "Turn over and stay in bed.",
  "listen_again": "Stay still and listen for the second backfire."
 }
}
